// Generates the Logto custom-JWT-claims script from config/sso.config.json `customJwtClaims`,
// so the config stays the single source of truth for mapped claims.
export const accessTokenScript = ({ fromCustomData = [], roles = false }) => `/**
 * Generated by scripts/provision.js from config/sso.config.json (customJwtClaims).
 * Do not edit in the Logto Console; re-run \`npm run provision\` instead.
 */
const getCustomJwtClaims = async ({ token, context, environmentVariables }) => {
  const customData = (context && context.user && context.user.customData) || {};
  const claims = {};
  for (const key of ${JSON.stringify(fromCustomData)}) {
    if (customData[key] !== undefined) claims[key] = customData[key];
  }${roles ? `
  claims.roles = ((context && context.user && context.user.roles) || []).map((role) => role.name);` : ''}
  return claims;
};`;
